#!/usr/bin/env node
/**
 * Writes `src/transaction/quereus-version.ts` from the installed `@quereus/quereus`. Run by this
 * package's `build` script, before `tsup`.
 *
 * `QUEREUS_ENGINE_ID` (`quereus@<version>`) is fixed when the plugin is built rather than looked up
 * when it loads: the lookup needs `node:fs` and `import.meta`, and neither exists in a browser or
 * under Hermes (React Native's JavaScript engine), where the plugin's root entry must still import.
 * See `QUEREUS_ENGINE_ID` in `src/transaction/quereus-engine.ts`.
 *
 * The generated file is committed, so typecheck and the specs that import `src` work on a fresh clone
 * without a build, and a Quereus bump shows up as a one-line diff. It is rewritten only when its
 * contents change, so an unchanged build leaves its timestamp alone.
 *
 * `installedQuereusVersion` is exported for `scripts/smoke.mjs`.
 */

import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import process from 'node:process';
import { fileURLToPath, pathToFileURL } from 'node:url';

const packageRoot = join(dirname(fileURLToPath(import.meta.url)), '..');
const OUTPUT = join(packageRoot, 'src', 'transaction', 'quereus-version.ts');

/**
 * The version of the `@quereus/quereus` this package resolves.
 *
 * `@quereus/quereus` exports no version, and its `exports` map has no `./package.json` subpath, so
 * reading that file by specifier throws `ERR_PACKAGE_PATH_NOT_EXPORTED`. It also defines only the
 * `import` condition, so `createRequire` cannot resolve it at all. Instead resolve the ESM entry
 * (`import.meta.resolve` is synchronous from Node 20.6), then walk up to the package's own
 * `package.json`. The name check skips any inner `package.json`, such as a `dist/` type marker.
 */
export function installedQuereusVersion() {
	let dir = dirname(fileURLToPath(import.meta.resolve('@quereus/quereus')));
	for (let i = 0; i < 6; i++) {
		try {
			const pkg = JSON.parse(readFileSync(join(dir, 'package.json'), 'utf8'));
			if (pkg.name === '@quereus/quereus' && pkg.version) return pkg.version;
		} catch { /* keep walking up */ }
		dir = dirname(dir);
	}
	throw new Error('Could not resolve the installed @quereus/quereus version');
}

function render(version) {
	return [
		'// Generated by scripts/write-quereus-version.mjs from the installed @quereus/quereus. Do not edit:',
		'// `yarn workspace @optimystic/quereus-plugin-optimystic build` rewrites it.',
		`export const QUEREUS_VERSION = '${version}';`,
		'',
	].join('\n');
}

function readOrEmpty(file) {
	try {
		return readFileSync(file, 'utf8');
	} catch {
		return '';
	}
}

function main() {
	const version = installedQuereusVersion();
	const content = render(version);
	// A Windows checkout may hold the committed file with CRLF endings; that is not a change.
	const changed = readOrEmpty(OUTPUT).replace(/\r\n/g, '\n') !== content;
	if (changed) writeFileSync(OUTPUT, content);
	const shown = relative(packageRoot, OUTPUT).split('\\').join('/');
	console.log(`write-quereus-version: @quereus/quereus ${version} -> ${shown}${changed ? '' : ' (unchanged)'}`);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main();
